/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: pixels, oklab, hue
 *   Constants: white, muted
 * Tests
 *   - keeps an already legible tone and preserves hue when it must darken one
 *   - lifts near-black artwork to a visible tone and keeps the neutral tone legible
 *   - lets a vivid subject outweigh a slightly larger grey field and ignores transparent pixels
 *   - falls back to the grey family for monochrome artwork and to null without opaque pixels
 *   - sampleArtworkTone
 *     - decodes the variant into a small canvas and derives its tone
 *     - rejects an image that cannot decode and resolves null without a canvas
 * @end-catalog */

import {
  artworkToneFromOklab,
  contrastRatio,
  dominantArtworkColor,
  rgbToOklab,
  sampleArtworkTone
} from './artworkTone';
import { neutralArtworkTone } from './useArtworkTone';

const white = '#ffffff';
const muted = '#b3b3b3';

/** Builds RGBA pixel data from [color, count] runs. */
const pixels = (...runs: Array<[readonly [number, number, number, number?], number]>) => new Uint8ClampedArray(
  runs.flatMap(([[red, green, blue, alpha = 255], count]) => Array.from({ length: count }, () => [red, green, blue, alpha]).flat())
);

const oklab = (color: string) => {
  const value = Number.parseInt(color.slice(1), 16);
  return rgbToOklab([(value >> 16) & 255, (value >> 8) & 255, value & 255]);
};

const hue = (color: string) => {
  const [, a, b] = oklab(color);
  return Math.atan2(b, a);
};

test.each([
  ['white', [255, 255, 255]],
  ['pale yellow', [255, 244, 140]],
  ['cyan', [0, 255, 255]],
  ['lime', [0, 255, 0]],
  ['saturated blue', [0, 0, 255]],
  ['black', [0, 0, 0]],
  ['mid grey', [128, 128, 128]]
] as const)('keeps white text at AA on the hero tone and muted text at AA on the pane tone for %s', (_name, rgb) => {
  const tone = artworkToneFromOklab(rgbToOklab(rgb));
  expect(tone.hero).toMatch(/^#[0-9a-f]{6}$/);
  expect(tone.pane).toMatch(/^#[0-9a-f]{6}$/);
  expect(contrastRatio(white, tone.hero)).toBeGreaterThanOrEqual(4.5);
  expect(contrastRatio(muted, tone.pane)).toBeGreaterThanOrEqual(4.5);
  expect(contrastRatio(white, tone.pane)).toBeGreaterThan(contrastRatio(white, tone.hero) - 0.001);
});

test('keeps an already legible tone and preserves hue when it must darken one', () => {
  const deepRed = artworkToneFromOklab(rgbToOklab([120, 20, 30]));
  expect(deepRed.hero).toBe('#78141e');
  const lightOrange = artworkToneFromOklab(rgbToOklab([255, 170, 90]));
  expect(Math.abs(hue(lightOrange.hero) - hue('#ffaa5a'))).toBeLessThan(0.15);
  expect(Math.abs(hue(lightOrange.pane) - hue('#ffaa5a'))).toBeLessThan(0.15);
});

test('lifts near-black artwork to a visible tone and keeps the neutral tone legible', () => {
  const tone = artworkToneFromOklab(rgbToOklab([4, 4, 6]));
  expect(oklab(tone.hero)[0]).toBeGreaterThan(0.27);
  expect(contrastRatio(white, neutralArtworkTone.hero)).toBeGreaterThanOrEqual(4.5);
  expect(contrastRatio(muted, neutralArtworkTone.pane)).toBeGreaterThanOrEqual(4.5);
});

test('lets a vivid subject outweigh a slightly larger grey field and ignores transparent pixels', () => {
  const color = dominantArtworkColor(pixels(
    [[128, 128, 128], 300],
    [[30, 90, 220], 220],
    [[255, 0, 0, 0], 500]
  ));
  expect(color).not.toBeNull();
  const [, a, b] = color!;
  const [, blueA, blueB] = rgbToOklab([30, 90, 220]);
  expect(Math.atan2(b, a)).toBeCloseTo(Math.atan2(blueB, blueA), 2);
});

test('falls back to the grey family for monochrome artwork and to null without opaque pixels', () => {
  const [, a, b] = dominantArtworkColor(pixels([[40, 40, 40], 10], [[200, 200, 200], 10]))!;
  expect(Math.hypot(a, b)).toBeLessThan(0.01);
  expect(dominantArtworkColor(pixels([[10, 200, 10, 20], 16]))).toBeNull();
  expect(dominantArtworkColor(new Uint8ClampedArray())).toBeNull();
});

describe('sampleArtworkTone', () => {
  const stubImage = (decode: () => Promise<void>) => {
    const created: Array<{ src: string }> = [];
    vi.stubGlobal('Image', class {
      decoding = '';
      src = '';
      constructor() { created.push(this); }
      decode = decode;
    });
    return created;
  };

  test('decodes the variant into a small canvas and derives its tone', async () => {
    const created = stubImage(() => Promise.resolve());
    const drawImage = vi.fn();
    vi.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue({
      drawImage,
      getImageData: () => ({ data: pixels([[200, 40, 60], 24 * 24]) })
    } as unknown as CanvasRenderingContext2D);

    const tone = await sampleArtworkTone('/content/images/0123456789abcdef01234567/v1/96.webp');

    expect(created[0].src).toBe('/content/images/0123456789abcdef01234567/v1/96.webp');
    expect(drawImage).toHaveBeenCalledWith(created[0], 0, 0, 24, 24);
    expect(tone).toEqual(artworkToneFromOklab(rgbToOklab([200, 40, 60])));
  });

  test('rejects an image that cannot decode and resolves null without a canvas', async () => {
    stubImage(() => Promise.reject(new Error('decode failed')));
    await expect(sampleArtworkTone('/missing.webp')).rejects.toThrow('decode failed');

    stubImage(() => Promise.resolve());
    vi.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue(null);
    await expect(sampleArtworkTone('/no-canvas.webp')).resolves.toBeNull();
  });
});
